//! Screens against an independent implementation in pandas, on a universe cut from the S&P 500
//! prices in `tests/sp500` with uneven histories, gaps, missing closes and a stale company. The
//! fixture, generated by `scripts/reference/screening.py`, holds the recipe of the universe and
//! the expected results, with the near misses the report lists.

#![allow(clippy::unwrap_used)]

use finalytics::screening::{ScreenOptions, Series};
use finalytics::{Date, Universe};
use serde_json::Value;

fn fixture() -> Value {
    serde_json::from_str(include_str!("fixtures/screening.json")).unwrap()
}

fn volume_of(k: usize, s: usize) -> f64 {
    1_000_000.0 + ((k * 7919 + s * 104_729) % 1000) as f64 * 1000.0
}

fn dividend_of(k: usize, s: usize) -> f64 {
    if (k + s).is_multiple_of(63) {
        0.25 * (1 + s % 3) as f64
    } else {
        0.0
    }
}

fn dates(value: &Value) -> Vec<Date> {
    value
        .as_array()
        .map(|a| {
            a.iter()
                .map(|d| d.as_str().unwrap().parse().unwrap())
                .collect()
        })
        .unwrap_or_default()
}

/// The universe of the fixture's recipe, rebuilt from the S&P 500 prices.
fn universe(f: &Value) -> Universe {
    let all = Universe::builder()
        .prices_csv(include_str!("../../../tests/sp500/prices.csv"))
        .fields_csv(include_str!("../../../tests/sp500/companies.csv"))
        .build()
        .unwrap();
    let index = Universe::from_csv(include_str!("../../../tests/sp500/index.csv")).unwrap();
    let names = |key: &str| -> Vec<String> {
        f[key]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap().to_owned())
            .collect()
    };
    let (no_sector, no_pe) = (names("no_sector"), names("no_pe"));
    let mut series = Vec::new();
    for (s, r) in f["recipe"].as_array().unwrap().iter().enumerate() {
        let id = r["id"].as_str().unwrap();
        let full = all.series(id).unwrap();
        let start: Option<Date> = r["start"].as_str().map(|d| d.parse().unwrap());
        let end: Option<Date> = r["end"].as_str().map(|d| d.parse().unwrap());
        let gaps: Vec<Vec<Date>> = r["gaps"]
            .as_array()
            .map(|g| g.iter().map(dates).collect())
            .unwrap_or_default();
        let kept: Vec<(Date, f64)> = full
            .dates
            .iter()
            .zip(&full.close)
            .filter(|(d, _)| start.is_none_or(|s| **d >= s) && end.is_none_or(|e| **d <= e))
            .filter(|(d, _)| !gaps.iter().any(|g| **d >= g[0] && **d <= g[1]))
            .map(|(d, c)| (*d, *c))
            .collect();
        let days: Vec<Date> = kept.iter().map(|p| p.0).collect();
        let missing = dates(&r["missing"]);
        let close: Vec<f64> = kept
            .iter()
            .map(|(d, c)| if missing.contains(d) { f64::NAN } else { *c })
            .collect();
        let no_volume = dates(&r["volume_missing"]);
        let volume: Vec<f64> = (0..days.len())
            .map(|k| {
                if no_volume.contains(&days[k]) {
                    f64::NAN
                } else {
                    volume_of(k, s)
                }
            })
            .collect();
        let dividends: Vec<f64> = (0..days.len()).map(|k| dividend_of(k, s)).collect();
        let mut x = Series::new(id, days, close);
        if r["volume"].as_bool() == Some(true) {
            x = x.with_volume(volume);
        }
        if r["dividends"].as_bool() == Some(true) {
            x = x.with_dividends(dividends);
        }
        if !no_sector.iter().any(|n| n == id) {
            x = x.with_field("sector", full.fields["sector"].clone());
        }
        if !no_pe.iter().any(|n| n == id) {
            x = x.with_field("pe_ratio", 8.0 + ((s * 37) % 29) as f64);
        }
        series.push(x);
    }
    let benchmark = f["benchmark"].as_str().unwrap();
    series.push(index.series(benchmark).unwrap());
    Universe::from_series(series)
        .unwrap()
        .with_benchmark(benchmark)
        .unwrap()
        .with_risk_free_rate(f["risk_free_rate"].as_f64().unwrap())
}

#[track_caller]
fn close(actual: Option<f64>, expected: &Value, what: &str) {
    match (actual, expected.as_f64()) {
        (None, None) => {}
        (Some(a), Some(e)) => assert!(
            (a - e).abs() <= 1e-9 * e.abs().max(1.0),
            "{what}: {a} against the reference {e}"
        ),
        (a, _) => panic!("{what}: {a:?} against the reference {expected}"),
    }
}

#[test]
fn screens_match_the_reference() {
    let f = fixture();
    let universe = universe(&f);
    // Three closes of KO are not numbers, and are left out with a warning.
    assert!(universe.warnings().issues()[0].message.contains("3 closes"));
    for case in f["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let options: ScreenOptions = serde_json::from_value(case["options"].clone()).unwrap();
        let screen = universe.screen_with(&options).unwrap();
        let r = &screen.results;
        let measures: Vec<&str> = r.measures.iter().map(|m| m.name()).collect();
        let expected: Vec<&str> = case["measures"]
            .as_array()
            .unwrap()
            .iter()
            .map(|m| m.as_str().unwrap())
            .collect();
        assert_eq!(measures, expected, "{name}: measures");
        let matches: Vec<&str> = case["matches"]
            .as_array()
            .unwrap()
            .iter()
            .map(|m| m.as_str().unwrap())
            .collect();
        assert_eq!(r.matches, matches, "{name}: matches");
        for (k, (actual, e)) in r
            .rules
            .iter()
            .zip(case["rules"].as_array().unwrap())
            .enumerate()
        {
            let counts = [actual.passed, actual.lacking, actual.remaining];
            let expected =
                ["passed", "lacking", "remaining"].map(|key| e[key].as_u64().unwrap() as usize);
            assert_eq!(counts, expected, "{name}: rule {k}");
        }
        let c = &case["coverage"];
        let coverage = [
            r.coverage.measured,
            r.coverage.too_short,
            r.coverage.stale,
            r.coverage.passed,
            r.coverage.matched,
        ];
        let expected = ["measured", "too_short", "stale", "passed", "matched"]
            .map(|key| c[key].as_u64().unwrap() as usize);
        assert_eq!(coverage, expected, "{name}: coverage");
        let counts = |key: &str| -> Vec<usize> {
            c[key]
                .as_array()
                .unwrap()
                .iter()
                .map(|n| n.as_u64().unwrap() as usize)
                .collect()
        };
        assert_eq!(r.coverage.lacking, counts("lacking"), "{name}: lacking");
        assert_eq!(
            r.coverage.lacking_history,
            counts("lacking_history"),
            "{name}: lacking for too short a history"
        );
        let rows = case["securities"].as_array().unwrap();
        assert_eq!(r.securities.len(), rows.len(), "{name}: securities");
        let mut compared = 0;
        for (s, e) in r.securities.iter().zip(rows) {
            let id = e["id"].as_str().unwrap();
            assert_eq!(s.id, id, "{name}");
            assert_eq!(
                serde_json::to_value(s.status).unwrap(),
                e["status"],
                "{name}: {id} status"
            );
            assert_eq!(
                s.passed,
                e["passed"].as_bool().unwrap(),
                "{name}: {id} passed"
            );
            assert_eq!(
                s.rank.map(|k| k as u64),
                e["rank"].as_u64(),
                "{name}: {id} rank"
            );
            for (key, d) in [("first_date", s.first_date), ("last_date", s.last_date)] {
                assert_eq!(
                    d.map(|d| d.to_string()),
                    e[key].as_str().map(str::to_owned),
                    "{name}: {id} {key}"
                );
            }
            for ((m, v), x) in measures
                .iter()
                .zip(&s.values)
                .zip(e["values"].as_array().unwrap())
            {
                close(*v, x, &format!("{name}: {id} {m}"));
                compared += usize::from(v.is_some());
            }
        }
        assert!(compared > 0, "{name}: no values compared");

        // The report's near misses and its exceptions in the data.
        let near: Vec<(&str, u64)> = screen
            .report
            .near_misses
            .iter()
            .map(|m| (m.id.as_str(), m.rule as u64))
            .collect();
        let expected: Vec<(&str, u64)> = case["near_misses"]
            .as_array()
            .unwrap()
            .iter()
            .map(|m| (m["id"].as_str().unwrap(), m["rule"].as_u64().unwrap()))
            .collect();
        assert_eq!(near, expected, "{name}: near misses");
        let as_of = case["options"]["as_of"].as_str().unwrap_or("2026-10-30");
        let ids = |keep: &dyn Fn(&Value) -> bool| -> Vec<String> {
            rows.iter()
                .filter(|e| keep(e))
                .map(|e| e["id"].as_str().unwrap().to_owned())
                .collect()
        };
        let x = &screen.report.exceptions;
        assert_eq!(x.stale, ids(&|e| e["status"] == "stale"), "{name}: stale");
        assert_eq!(
            x.too_short,
            ids(&|e| e["status"] == "too_short"),
            "{name}: too short"
        );
        // Each strip holds every security with a value, lowest first, its matches marked.
        for s in &screen.report.strips {
            assert!(
                s.points.windows(2).all(|w| w[0].value <= w[1].value),
                "{name}"
            );
            for p in &s.points {
                assert_eq!(p.matched, r.matches.contains(&p.id), "{name}: {}", p.id);
            }
        }

        // The report prints in 80 columns and names the exceptions in its line on the data.
        let text = screen.to_string();
        let html = screen.report.to_html(None);
        assert!(
            text.lines().all(|l| l.chars().count() <= 80),
            "{name}:\n{text}"
        );
        let data = &text[text.find("\nData\n").unwrap()..];
        let line = &html[html.find(r#"<p class="dline">"#).unwrap()..];
        for id in x.stale.iter().chain(&x.too_short).chain(&x.late) {
            assert!(data.contains(id.as_str()), "{name}: {id} in\n{data}");
            assert!(
                line.contains(&id.replace('&', "&amp;")),
                "{name}: {id} in the page"
            );
        }
        assert_eq!(
            x.late,
            ids(&|e| e["status"] != "stale" && e["last_date"].as_str().is_some_and(|d| d < as_of)),
            "{name}: late"
        );
    }
}
